function pngResponse(b64) {
  const binary = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  return new Response(binary, {
    headers: {
      'content-type': 'image/png',
      'cache-control': 'public, max-age=604800',
      'access-control-allow-origin': '*',
    },
  });
}

