async function fetchCheapFlights(token, departDate) {
  let url = `${TRAVELPAYOUTS_URL}?origin=${ORIGIN}&destination=-&currency=usd&token=${encodeURIComponent(token)}`;
  if (departDate) url += `&depart_date=${departDate}`;
  const res = await fetch(url, { headers: { 'X-Access-Token': token } });
  if (!res.ok) {
    throw new Error(`Travelpayouts API HTTP ${res.status}`);
  }
  const body = await res.json();
  if (!body.success) {
    throw new Error(`Travelpayouts API error: ${body.error || 'unknown'}`);
  }
  return body.data || {};
}

function nextMonths(count) {
  const now = new Date();
  const months = [];
  for (let i = 0; i < count; i++) {
    const d = new Date(now.getFullYear(), now.getMonth() + i, 1);
    months.push(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`);
  }
  return months;
}

async function fetchCheapFlightsForMonths(token, months) {
  const results = await Promise.allSettled(months.map((month) => fetchCheapFlights(token, month)));
  const merged = {};
  let successCount = 0;
  results.forEach((result, i) => {
    if (result.status !== 'fulfilled') return;
    successCount++;
    const month = months[i];
    for (const [destination, entries] of Object.entries(result.value)) {
      if (!merged[destination]) merged[destination] = {};
      for (const [key, entry] of Object.entries(entries || {})) {
        merged[destination][`${month}-${key}`] = entry;
      }
    }
  });
  if (successCount === 0) {
    throw new Error('Travelpayouts API failed for all months');
  }
  return merged;
}

async function fetchUsdToIls() {
  try {
    const res = await fetch(FX_URL);
    if (!res.ok) return { rate: null, error: `Frankfurter API HTTP ${res.status}` };
    const body = await res.json();
    const rate = body && body.rates && body.rates.ILS;
    return typeof rate === 'number'
      ? { rate, error: null }
      : { rate: null, error: `Frankfurter API unexpected response: ${JSON.stringify(body)}` };
  } catch (err) {
    return { rate: null, error: String((err && err.message) || err) };
  }
}

function buildSearchLink(destination, departureAt) {
  const date = departureAt ? departureAt.slice(0, 10) : '';
  const q = `Flights from ${ORIGIN} to ${destination}${date ? ' on ' + date : ''}`;
  return `https://www.google.com/travel/flights?q=${encodeURIComponent(q)}`;
}

function buildHotelSearchLink(destination, departureAt, returnAt) {
  if (!departureAt || !returnAt) return null;
  const checkin = departureAt.slice(0, 10);
  const checkout = returnAt.slice(0, 10);
  const info = AIRPORT_INFO[destination];
  const ss = info ? `${info[1]}, ${info[0]}` : destination;
  return `https://www.booking.com/searchresults.html?ss=${encodeURIComponent(ss)}&checkin=${checkin}&checkout=${checkout}`;
}

function extractDeals(data) {
  const deals = [];
  for (const [destination, entries] of Object.entries(data)) {
    for (const entry of Object.values(entries || {})) {
      if (typeof entry.price === 'number') {
        deals.push({
          destination,
          price: entry.price,
          airline: entry.airline || null,
          departureAt: entry.departure_at || null,
          returnAt: entry.return_at || null,
          link: buildSearchLink(destination, entry.departure_at),
        });
      }
    }
  }
  deals.sort((a, b) => a.price - b.price);
  return deals;
}

async function runScan(env, source) {
  const now = new Date().toISOString();
  const prev = await env.DEALS.get(KV_KEY, 'json');
  const cronRunCount = (prev && prev.cronRunCount) || 0;
  const nextCronRunCount = source === 'cron' ? cronRunCount + 1 : cronRunCount;
  const fx = await fetchUsdToIls();
  const usdToIls = fx.rate || (prev && prev.usdToIls) || null;
  const fxError = fx.error;

  try {
    const data = await fetchCheapFlightsForMonths(env.TRAVELPAYOUTS_TOKEN, nextMonths(12));
    const deals = extractDeals(data);
    await env.DEALS.put(
      KV_KEY,
      JSON.stringify({ updatedAt: now, deals, error: null, lastRunSource: source, cronRunCount: nextCronRunCount, usdToIls, fxError })
    );
  } catch (err) {
    await env.DEALS.put(
      KV_KEY,
      JSON.stringify({
        updatedAt: now,
        deals: (prev && prev.deals) || [],
        error: String((err && err.message) || err),
        lastRunSource: source,
        cronRunCount: nextCronRunCount,
        usdToIls,
        fxError,
      })
    );
  }
}

function esc(value) {
  return String(value ?? '').replace(/[&<>"']/g, (ch) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[ch]));
}

function formatDate(iso) {
  if (!iso) return '-';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return esc(iso);
  return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear();
}

function nightsBetween(departureAt, returnAt) {
  if (!departureAt || !returnAt) return null;
  const d1 = new Date(departureAt);
  const d2 = new Date(returnAt);
  if (Number.isNaN(d1.getTime()) || Number.isNaN(d2.getTime())) return null;
  const day1 = new Date(d1.getFullYear(), d1.getMonth(), d1.getDate());
  const day2 = new Date(d2.getFullYear(), d2.getMonth(), d2.getDate());
  const nights = Math.round((day2 - day1) / 86400000);
  return nights >= 0 ? nights : null;
}

const HEBREW_DAY_NAMES = ['ראשון', 'שני', 'שלישי', 'רביעי', 'חמישי', 'שישי', 'שבת'];

function hebrewDayName(iso) {
  if (!iso) return null;
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return null;
  return HEBREW_DAY_NAMES[d.getDay()];
}

function daysRangeLabel(departureAt, returnAt) {
  const d1 = hebrewDayName(departureAt);
  const d2 = hebrewDayName(returnAt);
  if (!d1 || !d2) return null;
  return `ימים ${d1} עד ${d2}`;
}

const ISRAELI_HOLIDAYS = {};
function addHoliday(name, startIso, days) {
  const start = new Date(`${startIso}T00:00:00`);
  for (let i = 0; i < days; i++) {
    const d = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i);
    const iso = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    ISRAELI_HOLIDAYS[iso] = name;
  }
}
