async function renderPage(env, maxPrice, month, country, minNights, maxNights, departFrom, departTo, returnFrom, returnTo) {
  const stored = await env.DEALS.get(KV_KEY, 'json');
  const allDeals = (stored && stored.deals) || [];
  const preDateDeals = allDeals
    .filter((d) => d.price <= maxPrice)
    .filter((d) => !month || (d.departureAt && d.departureAt.slice(0, 7) === month))
    .filter((d) => !country || (AIRPORT_INFO[d.destination] && AIRPORT_INFO[d.destination][0] === country))
    .filter((d) => {
      if (minNights == null && maxNights == null) return true;
      const nights = nightsBetween(d.departureAt, d.returnAt);
      if (nights === null) return false;
      if (minNights != null && nights < minNights) return false;
      if (maxNights != null && nights > maxNights) return false;
      return true;
    });
  const deals = preDateDeals
    .filter((d) => !departFrom || (d.departureAt && d.departureAt.slice(0, 10) >= departFrom))
    .filter((d) => !departTo || (d.departureAt && d.departureAt.slice(0, 10) <= departTo))
    .filter((d) => !returnFrom || (d.returnAt && d.returnAt.slice(0, 10) >= returnFrom))
    .filter((d) => !returnTo || (d.returnAt && d.returnAt.slice(0, 10) <= returnTo));
  const updatedAt = stored && stored.updatedAt
    ? new Date(stored.updatedAt).toLocaleString('he-IL', { timeZone: 'Asia/Jerusalem' })
    : 'טרם עודכן';
  const error = stored && stored.error;
  const usdToIls = stored && stored.usdToIls;

  const monthQS = month ? `&month=${month}` : '';
  const countryQS = country ? `&country=${encodeURIComponent(country)}` : '';
  const nightsQS = (minNights != null ? `&minNights=${minNights}` : '') + (maxNights != null ? `&maxNights=${maxNights}` : '');
  const datesQS = (departFrom ? `&departFrom=${departFrom}` : '')
    + (departTo ? `&departTo=${departTo}` : '')
    + (returnFrom ? `&returnFrom=${returnFrom}` : '')
    + (returnTo ? `&returnTo=${returnTo}` : '');
  const presetLinks = PRICE_PRESETS.map((p) =>
    p === maxPrice ? `<strong>$${p}</strong>` : `<a href="/?max=${p}${monthQS}${countryQS}${nightsQS}${datesQS}">$${p}</a>`
  ).join(' | ');

  const monthOptions = nextMonths(12);
  const monthLinks = [
    month ? `<a href="/?max=${maxPrice}${countryQS}${nightsQS}${datesQS}">הכל</a>` : '<strong>הכל</strong>',
    ...monthOptions.map((m) => {
      const label = new Date(`${m}-01T00:00:00`).toLocaleString('he-IL', { month: 'long' });
      return m === month ? `<strong>${label}</strong>` : `<a href="/?max=${maxPrice}&month=${m}${countryQS}${nightsQS}${datesQS}">${label}</a>`;
    }),
  ].join(' | ');

  const countryOptions = Array.from(
    new Set(
      allDeals.filter((d) => AIRPORT_INFO[d.destination]).map((d) => AIRPORT_INFO[d.destination][0])
    )
  ).sort((a, b) => a.localeCompare('he'));

  const availableDepartDates = Array.from(
    new Set(preDateDeals.filter((d) => d.departureAt).map((d) => d.departureAt.slice(0, 10)))
  );
  const availableReturnDates = Array.from(
    new Set(preDateDeals.filter((d) => d.returnAt).map((d) => d.returnAt.slice(0, 10)))
  );

  function ilsLabel(price) {
    if (!usdToIls) return '';
    return ` (₪${Math.round(price * usdToIls).toLocaleString('he-IL')})`;
  }

  function dateRangeLabel(from, to, placeholder) {
    if (from && to) return `${formatDate(from)} - ${formatDate(to)}`;
    if (from) return `${formatDate(from)} - ...`;
    if (to) return `... - ${formatDate(to)}`;
    return placeholder;
  }

  function dateSummaryLabel(departFrom, departTo, returnFrom, returnTo) {
    const departPart = dateRangeLabel(departFrom, departTo, null);
    const returnPart = dateRangeLabel(returnFrom, returnTo, null);
    if (!departPart && !returnPart) return 'בחר תאריכי טיול';
    if (departPart && returnPart) return `${departPart} ← ${returnPart}`;
    return departPart || returnPart;
  }

  const rows = deals
    .map((d) => {
      const hotelLink = buildHotelSearchLink(d.destination, d.departureAt, d.returnAt);
      return `
        <tr>
          <td>${esc(d.destination)}</td>
          <td class="price" data-usd="${d.price}">$${d.price.toFixed(0)}${ilsLabel(d.price)}</td>
          <td>${esc(AIRLINE_NAMES[d.airline] || d.airline || '-')}</td>
          <td>${formatDate(d.departureAt)}</td>
          <td>${d.returnAt ? formatDate(d.returnAt) : '-'}</td>
          <td>${nightsBetween(d.departureAt, d.returnAt) ?? '-'}</td>
          <td><a class="purchase-link" data-base-link="${esc(d.link)}" href="${esc(d.link)}" target="_blank" rel="noopener">לרכישה</a></td>
          <td>${hotelLink ? `<a href="${esc(hotelLink)}" target="_blank" rel="noopener">מלונות</a>` : '-'}</td>
        </tr>`;
    })
    .join('');

  const table = deals.length
    ? `
      <table>
        <thead>
          <tr><th>יעד</th><th>מחיר</th><th>חברת תעופה</th><th>יציאה</th><th>חזור</th><th>לילות</th><th>קישור</th><th>מלונות</th></tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>`
    : `<p class="empty">אין כרגע טיסות מתחת ל-$${maxPrice} מנתב"ג.</p>`;

  const cards = deals
    .map((d) => {
      const info = AIRPORT_INFO[d.destination];
      const country = info ? info[0] : d.destination;
      const city = info ? info[1] : '';
      const airlineName = AIRLINE_NAMES[d.airline] || d.airline || '-';
      const nights = nightsBetween(d.departureAt, d.returnAt);
      const daysLabel = daysRangeLabel(d.departureAt, d.returnAt);
      const datesText = d.returnAt ? `${formatDate(d.departureAt)} &larr; ${formatDate(d.returnAt)}` : formatDate(d.departureAt);
      const hotelLink = buildHotelSearchLink(d.destination, d.departureAt, d.returnAt);
      return `
        <article class="card-list">
          <div class="head">
            <div class="dest">
              <div class="country">${esc(country)}</div>
              ${city ? `<div class="city">${esc(city)} &middot; ${esc(d.destination)}</div>` : `<div class="city">${esc(d.destination)}</div>`}
            </div>
            <span class="brand">FlyDeal</span>
          </div>
          <div class="rows">
            ${daysLabel ? `<div class="item">${CARD_ICONS.week}<span>${esc(daysLabel)}</span></div>` : ''}
            <div class="item">${CARD_ICONS.calendar}<span class="tabular">${datesText}</span></div>
            <div class="item">${CARD_ICONS.moon}<span>${nights !== null ? `<b class="tabular">${nights}</b> לילות` : '-'}</span></div>
            <div class="item">${CARD_ICONS.plane}<span>${esc(airlineName)}</span></div>
            ${hotelLink ? `<div class="item">${CARD_ICONS.hotel}<a class="hotel-link" href="${esc(hotelLink)}" target="_blank" rel="noopener">חיפוש מלונות ביעד</a></div>` : ''}
          </div>
          <div class="price-cta">
            <a class="card-link purchase-link" data-base-link="${esc(d.link)}" href="${esc(d.link)}" target="_blank" rel="noopener">לרכישה &#8592;</a>
            <div class="price tabular" data-usd="${d.price}">${usdToIls ? `<sup>₪</sup><span class="ils-amount">${Math.round(d.price * usdToIls).toLocaleString('he-IL')}</span><span class="ils">$<span class="usd-amount">${d.price.toFixed(0)}</span></span>` : `<sup>$</sup><span class="usd-amount">${d.price.toFixed(0)}</span>`}</div>
          </div>
        </article>`;
    })
    .join('');

  const cardsView = deals.length ? `<div class="cards-grid">${cards}</div>` : `<p class="empty">אין כרגע טיסות מתחת ל-$${maxPrice} מנתב"ג.</p>`;

  const html = `<!DOCTYPE html>
<html lang="he" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>FlyDeal - טיסות זולות מישראל</title>
<link rel="manifest" href="/manifest.webmanifest">
<meta name="theme-color" content="#0ea5e9">
<link rel="apple-touch-icon" href="/icon-192.png">
<link rel="icon" type="image/svg+xml" href="data:image/svg+xml;base64,">
<style>
  :root {
    --bg: #f5f5f7;
    --ink: #1c1c1e;
    --ink-soft: #666;
    --link: #0066cc;
    --surface: #fff;
    --surface-2: #eef;
    --border: #eee;
    --price: #2e7d32;
    --toggle-border: #cfd8e3;
    --toggle-bg: #fff;
    --toggle-hover: #f0f4f8;
    --error-bg: #ffe5e5;
    --error-border: #ff3b30;
    --error-ink: #b30000;
    --card-bg: linear-gradient(135deg, #0ea5e9 0%, #22c55e 100%);
    --card-border: none;
    --card-brand-bg: rgba(255,255,255,0.2);
    --card-city-opacity: 0.88;
    --card-link-color: #0f766e;
    --card-icon: rgba(255,255,255,0.9);

    --fs-brand: 0.68rem;
    --fs-country: 1.1rem;
    --fs-city: 0.78rem;
    --fs-item: 0.85rem;
    --fs-icon: 16px;
    --fs-price: 1.9rem;
    --fs-price-sup: 0.95rem;
    --fs-ils: 0.82rem;
    --fs-cta: 0.8rem;
    --card-pad: 1.15rem 1.3rem;
    --row-gap: 0.55rem;
  }
  body[data-textsize="m"] {
    --fs-brand: 0.74rem;
    --fs-country: 1.25rem;
    --fs-city: 0.88rem;
    --fs-item: 0.98rem;
    --fs-icon: 18px;
    --fs-price: 2.2rem;
    --fs-price-sup: 1.05rem;
    --fs-ils: 0.92rem;
    --fs-cta: 0.9rem;
    --card-pad: 1.3rem 1.45rem;
    --row-gap: 0.65rem;
  }
  body[data-textsize="l"] {
    --fs-brand: 0.8rem;
    --fs-country: 1.45rem;
    --fs-city: 1rem;
    --fs-item: 1.1rem;
    --fs-icon: 20px;
    --fs-price: 2.5rem;
    --fs-price-sup: 1.2rem;
    --fs-ils: 1rem;
    --fs-cta: 1rem;
    --card-pad: 1.4rem 1.55rem;
    --row-gap: 0.75rem;
  }
  body[data-textsize="xl"] {
    --fs-brand: 0.88rem;
    --fs-country: 1.7rem;
    --fs-city: 1.15rem;
    --fs-item: 1.25rem;
    --fs-icon: 23px;
    --fs-price: 2.9rem;
    --fs-price-sup: 1.35rem;
    --fs-ils: 1.12rem;
    --fs-cta: 1.1rem;
    --card-pad: 1.55rem 1.65rem;
    --row-gap: 0.9rem;
  }
  @media (prefers-color-scheme: dark) {
    :root {
      --bg: #262624;
      --ink: #faf9f5;
      --ink-soft: #a8a29e;
      --link: #38bdf8;
      --surface: #2f2e2c;
      --surface-2: #3a3936;
      --border: rgba(250,249,245,0.09);
      --price: #4ade80;
      --toggle-border: rgba(250,249,245,0.09);
      --toggle-bg: #2f2e2c;
      --toggle-hover: #3a3936;
      --error-bg: #3a2422;
      --error-border: #8a3b34;
      --error-ink: #ffb4a8;
      --card-bg: #302f2c;
      --card-border: 1px solid rgba(255,255,255,0.55);
      --card-brand-bg: rgba(255,255,255,0.14);
      --card-city-opacity: 0.78;
      --card-link-color: #1c1c1a;
      --card-icon: #38bdf8;
    }
  }

  body { font-family: system-ui, sans-serif; background:var(--bg); margin:0; padding:16px; color:var(--ink); }
  header { display:flex; align-items:center; gap:10px; }
  header svg { width:40px; height:40px; flex-shrink:0; }
  h1 { font-size:1.3em; margin:0; }
  .meta { color:var(--ink-soft); font-size:0.9em; margin-bottom:8px; }
  .presets { margin-bottom:16px; }
  .presets a { color:var(--link); text-decoration:none; }
  .country-search input {
    font: inherit;
    color: var(--ink);
    background: var(--toggle-bg);
    border: 1px solid var(--toggle-border);
    border-radius: 999px;
    padding: 0.3rem 0.9rem;
    margin-inline-start: 0.4rem;
    min-width: 12rem;
  }
  .country-search #clearCountry { margin-inline-start: 0.6rem; }
  #minNights, #maxNights {
    font: inherit;
    color: var(--ink);
    background: var(--toggle-bg);
    border: 1px solid var(--toggle-border);
    border-radius: 999px;
    padding: 0.3rem 0.9rem;
    margin-inline-start: 0.4rem;
  }
  .date-btn {
    font: inherit;
    color: var(--ink);
    background: var(--toggle-bg);
    border: 1px solid var(--toggle-border);
    border-radius: 999px;
    padding: 0.3rem 0.9rem;
    margin-inline-start: 0.4rem;
    cursor: pointer;
  }
  .date-btn:hover { background: var(--toggle-hover); }
  #clearDates { margin-inline-start: 0.6rem; }
  .calendar-tabs { display: flex; gap: 0.4rem; margin-bottom: 0.7rem; }
  .cal-tab {
    flex: 1;
    font: inherit;
    font-size: 0.8rem;
    color: var(--ink-soft);
    background: var(--toggle-bg);
    border: 1px solid var(--toggle-border);
    border-radius: 999px;
    padding: 0.4rem 0.5rem;
    cursor: pointer;
  }
  .cal-tab.active { color: var(--ink); border-color: #0ea5e9; font-weight: 700; }
  .calendar-modal-backdrop {
    position: fixed; inset: 0; background: rgba(0,0,0,0.5);
    display: flex; align-items: center; justify-content: center;
    z-index: 100; padding: 1rem;
  }
  .calendar-modal {
    background: var(--surface); color: var(--ink);
    border: 1px solid var(--toggle-border); border-radius: 14px;
    padding: 1rem; width: 100%; max-width: 340px;
  }
  .calendar-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.6rem; font-weight: 700; }
  .cal-nav { background: none; border: none; color: var(--ink); font-size: 1.2rem; cursor: pointer; padding: 0.2rem 0.6rem; }
  .calendar-weekdays { display: grid; grid-template-columns: repeat(7, 1fr); text-align: center; font-size: 0.75rem; color: var(--ink-soft); margin-bottom: 0.3rem; }
  .calendar-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 0.2rem; }
  .calendar-day { position: relative; aspect-ratio: 1; border: 2px solid transparent; background: var(--toggle-bg); color: var(--ink); border-radius: 8px; cursor: pointer; font: inherit; font-weight: 700; }
  .calendar-day.available { border-color: #22c55e; }
  .calendar-day.range-start { background: #0ea5e9; color: #fff; }
  .calendar-day:hover:not(:disabled) { background: var(--toggle-hover); }
  .calendar-day.empty { background: none; cursor: default; }
  .calendar-day:disabled { opacity: 0.35; cursor: not-allowed; font-weight: 400; }
  .dot { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-inline-end: 0.35rem; flex-shrink: 0; }
  .dot.available { background: #22c55e; }
  .holiday-list { list-style: none; margin: 0.7rem 0 0; padding: 0; font-size: 0.85rem; }
  .holiday-list li { display: flex; align-items: center; padding: 0.15rem 0; }
  .calendar-legend { font-size: 0.8rem; color: var(--ink-soft); margin: 0.4rem 0 0; }
  .error { background:var(--error-bg); border:1px solid var(--error-border); color:var(--error-ink); padding:10px; border-radius:8px; margin-bottom:16px; }
  table { width:100%; border-collapse:collapse; background:var(--surface); border-radius:10px; overflow:hidden; }
  th, td { padding:8px 10px; text-align:right; border-bottom:1px solid var(--border); }
  th { background:var(--surface-2); }
  td a { color: var(--link); }
  .price { color:var(--price); font-weight:bold; }
  .empty { color:var(--ink-soft); }

  .view-toggle {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    appearance: none;
    border: 1px solid var(--toggle-border);
    background: var(--toggle-bg);
    color: var(--ink);
    font: inherit;
    font-size: 0.85rem;
    font-weight: 600;
    padding: 0.4rem 0.8rem;
    border-radius: 999px;
    cursor: pointer;
    margin-bottom: 16px;
  }
  .view-toggle:hover { background: var(--toggle-hover); }
  .view-toggle svg { width: 16px; height: 16px; flex-shrink: 0; }

  .icon-btn {
    appearance: none;
    border: 1px solid var(--toggle-border);
    background: var(--toggle-bg);
    color: var(--ink-soft);
    font: inherit;
    font-size: 0.78rem;
    font-weight: 800;
    width: 2.1rem;
    height: 2.1rem;
    border-radius: 50%;
    cursor: pointer;
    margin-inline-start: 0.4rem;
  }
  .icon-btn:hover { background: var(--toggle-hover); color: var(--ink); }

  .cards-grid { display: grid; grid-template-columns: 1fr; gap: 1rem; }

  .card-list {
    border-radius: 16px;
    background: var(--card-bg);
    border: var(--card-border);
    color: #fff;
    box-shadow: 0 1px 2px rgba(30,25,15,0.08), 0 8px 24px -12px rgba(30,25,15,0.35);
    padding: var(--card-pad);
  }
  .card-list .head { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 0.9rem; }
  .card-list .brand {
    background: var(--card-brand-bg);
    font-size: var(--fs-brand);
    font-weight: 800;
    letter-spacing: 0.04em;
    padding: 0.3rem 0.7rem;
    border-radius: 999px;
    white-space: nowrap;
  }
  .card-list .dest .country { font-size: var(--fs-country); font-weight: 800; line-height: 1.15; }
  .card-list .dest .city { font-size: var(--fs-city); opacity: var(--card-city-opacity); margin-top: 0.15rem; }

  .passengers {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    color: var(--ink-soft);
    font-size: 0.9em;
    margin-bottom: 8px;
  }
  .passengers .step-btn {
    appearance: none;
    border: 1px solid var(--toggle-border);
    background: var(--toggle-bg);
    color: var(--ink);
    font: inherit;
    font-weight: 700;
    width: 1.7rem;
    height: 1.7rem;
    border-radius: 50%;
    cursor: pointer;
    line-height: 1;
  }
  .passengers .step-btn:hover { background: var(--toggle-hover); }
  .passengers #paxCount { font-weight: 700; color: var(--ink); min-width: 1.2em; text-align: center; display: inline-block; }

  .card-list .rows { display: flex; flex-direction: column; gap: var(--row-gap); margin-bottom: 1.05rem; }
  .card-list .item { display: flex; align-items: center; gap: 0.6rem; font-size: var(--fs-item); }
  .card-list .item svg { width: var(--fs-icon); height: var(--fs-icon); flex-shrink: 0; color: var(--card-icon); }
  .card-list .item b { font-weight: 700; }
  .card-list .item .hotel-link { color: inherit; text-decoration: underline; text-underline-offset: 0.15em; }

  .card-list .price-cta {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }
  .card-list .price {
    font-family: ui-monospace, monospace;
    font-size: var(--fs-price);
    font-weight: 800;
    line-height: 1;
    letter-spacing: -0.02em;
    white-space: nowrap;
    color: #fff;
  }
  .card-list .price sup { font-size: var(--fs-price-sup); font-weight: 700; margin-inline-end: 0.1rem; }
  .card-list .price .ils { display: block; font-size: var(--fs-ils); font-weight: 700; opacity: 0.9; }
  .card-list .card-link {
    font-size: var(--fs-cta);
    font-weight: 800;
    color: var(--card-link-color);
    background: #fff;
    padding: 0.5rem 1rem;
    border-radius: 999px;
    text-decoration: none;
    white-space: nowrap;
  }

  body[data-view="table"] .cards-view { display: none; }
  body[data-view="cards"] .table-view { display: none; }
</style>
</head>
<body data-view="cards">
  <header>
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" role="img" aria-label="FlyDeal">
      <defs>
        <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stop-color="#0ea5e9"/>
          <stop offset="100%" stop-color="#22c55e"/>
        </linearGradient>
      </defs>
      <circle cx="12" cy="12" r="12" fill="url(#bg)"/>
      <g transform="translate(3.6,3.6) scale(0.7)">
        <path d="M2.01,21L23,12L2.01,3L2,10l15,2l-15,2L2.01,21z" fill="#ffffff"/>
      </g>
    </svg>
    <h1>FlyDeal - טיסות זולות מ-TLV${country ? ` ל${esc(country)}` : ''} (עד $${maxPrice} לנוסע)</h1>
  </header>
  <p class="meta">עודכן לאחרונה: ${esc(updatedAt)} (${stored && stored.lastRunSource === 'manual' ? 'הרצה ידנית' : 'סריקה אוטומטית'}) | מתעדכן אוטומטית כל 15 דקות - רענן את הדף כדי לראות נתונים חדשים</p>
  <p class="meta">מספר סריקות אוטומטיות שבוצעו עד כה: <strong>${(stored && stored.cronRunCount) || 0}</strong> - המספר הזה עולה רק מהסריקה האוטומטית (לא מ-/run הידני), כדי שתוכל לוודא שה-Cron באמת רץ לבד</p>
  <p class="presets">סף מחיר: ${presetLinks}</p>
  <p class="presets">חודש: ${monthLinks}</p>
  <p class="presets country-search">
    יעד:
    <input type="text" id="countryInput" list="countryDatalist" placeholder="הקלד שם מדינה..." autocomplete="off" value="${country ? esc(country) : ''}">
    <datalist id="countryDatalist">
      ${countryOptions.map((c) => `<option value="${esc(c)}">`).join('')}
    </datalist>
    ${country ? `<a href="/?max=${maxPrice}${monthQS}${nightsQS}${datesQS}" id="clearCountry">נקה יעד</a>` : ''}
  </p>
  <p class="presets">
    לילות:
    <select id="minNights">
      <option value="">הכל</option>
      ${Array.from({ length: 21 }, (_, i) => i + 1)
        .map((n) => `<option value="${n}" ${minNights === n ? 'selected' : ''}>${n}</option>`)
        .join('')}
    </select>
    עד
    <select id="maxNights">
      <option value="">הכל</option>
      ${Array.from({ length: 21 }, (_, i) => i + 1)
        .map((n) => `<option value="${n}" ${maxNights === n ? 'selected' : ''}>${n}</option>`)
        .join('')}
    </select>
  </p>
  <p class="presets">
    תאריכים:
    <button type="button" id="dateRangeBtn" class="date-btn">${dateSummaryLabel(departFrom, departTo, returnFrom, returnTo)}</button>
    <a href="/?max=${maxPrice}${countryQS}" id="clearDates"${departFrom || departTo || returnFrom || returnTo ? '' : ' style="display:none"'}>נקה תאריכים</a>
  </p>
  <p class="passengers">
    <button type="button" id="paxMinus" class="step-btn" aria-label="הפחת נוסע">&minus;</button>
    מספר נוסעים: <span id="paxCount">1</span>
    <button type="button" id="paxPlus" class="step-btn" aria-label="הוסף נוסע">+</button>
  </p>
  ${usdToIls ? `<p class="meta">שער המרה המוצג: $1 = ₪${usdToIls.toFixed(2)}</p>` : ''}
  ${!usdToIls && stored && stored.fxError ? `<p class="meta">לא הצלחתי לעדכן שער חליפין: ${esc(stored.fxError)}</p>` : ''}
  ${error ? `<div class="error">שגיאה בסריקה האחרונה: ${esc(error)} (הרשימה למטה מהסריקה המוצלחת הקודמת אם קיימת)</div>` : ''}
  <button type="button" id="viewToggle" class="view-toggle" aria-pressed="true">
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <rect x="3" y="4" width="7" height="16" rx="1.5"></rect>
      <rect x="14" y="4" width="7" height="7" rx="1.5"></rect>
      <rect x="14" y="14" width="7" height="6" rx="1.5"></rect>
    </svg>
    <span id="viewToggleLabel">תצוגת טבלה</span>
  </button>
  <button type="button" id="textSizeBtn" class="icon-btn" aria-label="שנה גודל טקסט בכרטיסים" title="שנה גודל טקסט בכרטיסים">Aa</button>
  <div class="table-view">${table}</div>
  <div class="cards-view">${cardsView}</div>
  <script>
    (function () {
      var body = document.body;
      var btn = document.getElementById('viewToggle');
      var label = document.getElementById('viewToggleLabel');
      btn.addEventListener('click', function () {
        var showingCards = body.dataset.view === 'cards';
        body.dataset.view = showingCards ? 'table' : 'cards';
        label.textContent = showingCards ? 'תצוגת כרטיסים' : 'תצוגת טבלה';
        btn.setAttribute('aria-pressed', String(!showingCards));
      });
    })();
    (function () {
      var sizes = ['original', 'm', 'l', 'xl'];
      var key = 'flydeal-textsize';
      var body = document.body;
      var btn = document.getElementById('textSizeBtn');
      var saved = localStorage.getItem(key);
      if (saved && sizes.indexOf(saved) !== -1 && saved !== 'original') {
        body.dataset.textsize = saved;
      }
      btn.addEventListener('click', function () {
        var current = sizes.indexOf(body.dataset.textsize || 'original');
        var next = sizes[(current + 1) % sizes.length];
        if (next === 'original') {
          delete body.dataset.textsize;
        } else {
          body.dataset.textsize = next;
        }
        localStorage.setItem(key, next);
      });
    })();
    (function () {
      var FX_RATE = ${usdToIls ? usdToIls : 'null'};
      var key = 'flydeal-passengers';
      var min = 1, max = 9;
      var saved = parseInt(localStorage.getItem(key), 10);
      var count = (saved >= min && saved <= max) ? saved : 1;
      var countEl = document.getElementById('paxCount');

      function updatePrices() {
        document.querySelectorAll('td.price[data-usd]').forEach(function (td) {
          var base = parseFloat(td.dataset.usd);
          var total = base * count;
          var text = '$' + Math.round(total);
          if (FX_RATE) text += ' (₪' + Math.round(total * FX_RATE).toLocaleString('he-IL') + ')';
          td.textContent = text;
        });
        document.querySelectorAll('.card-list .price[data-usd]').forEach(function (el) {
          var base = parseFloat(el.dataset.usd);
          var total = base * count;
          var usdAmount = el.querySelector('.usd-amount');
          if (usdAmount) usdAmount.textContent = Math.round(total);
          var ilsAmount = el.querySelector('.ils-amount');
          if (ilsAmount && FX_RATE) ilsAmount.textContent = Math.round(total * FX_RATE).toLocaleString('he-IL');
        });
      }

      function updateLinks() {
        document.querySelectorAll('a.purchase-link').forEach(function (a) {
          var base = a.dataset.baseLink;
          try {
            var url = new URL(base);
            var q = url.searchParams.get('q');
            if (q) {
              q = q.replace(/ for \\d+ adults?$/, '');
              if (count > 1) q += ' for ' + count + ' adults';
              url.searchParams.set('q', q);
            }
            a.href = url.toString();
          } catch (e) {}
        });
      }

      function render() {
        countEl.textContent = count;
        updatePrices();
        updateLinks();
      }

      document.getElementById('paxMinus').addEventListener('click', function () {
        if (count > min) { count--; localStorage.setItem(key, count); render(); }
      });
      document.getElementById('paxPlus').addEventListener('click', function () {
        if (count < max) { count++; localStorage.setItem(key, count); render(); }
      });

      render();
    })();
    (function () {
      var MAX_PRICE = ${maxPrice};
      var MONTH_QS = '${monthQS}';
      var COUNTRY_QS = '${countryQS}';
      var NIGHTS_QS = '${nightsQS}';
      var DATES_QS = '${datesQS}';

      var input = document.getElementById('countryInput');
      if (input) {
        var options = Array.from(document.querySelectorAll('#countryDatalist option')).map(function (o) {
          return o.value;
        });
        function goCountry() {
          var value = input.value.trim();
          if (!value) {
            location.href = '/?max=' + MAX_PRICE + MONTH_QS + NIGHTS_QS + DATES_QS;
          } else if (options.indexOf(value) !== -1) {
            location.href = '/?max=' + MAX_PRICE + '&country=' + encodeURIComponent(value) + NIGHTS_QS + DATES_QS;
          }
        }
        input.addEventListener('change', goCountry);
        input.addEventListener('keydown', function (e) {
          if (e.key === 'Enter') goCountry();
        });
      }

      var minSel = document.getElementById('minNights');
      var maxSel = document.getElementById('maxNights');
      if (minSel && maxSel) {
        function goNights() {
          var min = minSel.value;
          var max = maxSel.value;
          var qs = (min ? '&minNights=' + min : '') + (max ? '&maxNights=' + max : '');
          location.href = '/?max=' + MAX_PRICE + MONTH_QS + COUNTRY_QS + qs + DATES_QS;
        }
        minSel.addEventListener('change', goNights);
        maxSel.addEventListener('change', goNights);
      }
    })();
    (function () {
      var dateBtn = document.getElementById('dateRangeBtn');
      if (!dateBtn) return;

      var MAX_PRICE = ${maxPrice};
      var COUNTRY_QS = '${countryQS}';
      var HOLIDAYS = ${JSON.stringify(ISRAELI_HOLIDAYS)};
      var AVAILABLE_DEPART = ${JSON.stringify(availableDepartDates)};
      var AVAILABLE_RETURN = ${JSON.stringify(availableReturnDates)};
      var departFrom = ${departFrom ? `'${departFrom}'` : 'null'};
      var departTo = ${departTo ? `'${departTo}'` : 'null'};
      var returnFrom = ${returnFrom ? `'${returnFrom}'` : 'null'};
      var returnTo = ${returnTo ? `'${returnTo}'` : 'null'};
      var activeTab = 'depart';
      var weekdayNames = ['א', 'ב', 'ג', 'ד', 'ה', 'ו', 'ש'];
      var HOLIDAY_COLORS = {
        'ראש השנה': '#f59e0b',
        'יום כיפור': '#ef4444',
        'סוכות': '#a855f7',
        'שמחת תורה': '#ec4899',
        'חנוכה': '#3b82f6',
        'ט"ו בשבט': '#84cc16',
        'פורים': '#eab308',
        'פסח': '#06b6d4',
        'יום הזיכרון': '#64748b',
        'יום העצמאות': '#0ea5e9',
        'ל"ג בעומר': '#f97316',
        'שבועות': '#14b8a6',
        'תשעה באב': '#78716c',
      };
      function holidayColor(name) { return HOLIDAY_COLORS[name] || '#f59e0b'; }

      function pad(n) { return String(n).padStart(2, '0'); }
      function toIso(y, m, d) { return y + '-' + pad(m + 1) + '-' + pad(d); }
      function labelOf(iso) { return iso.split('-').reverse().join('/'); }
      function rangeLabel(from, to, placeholder) {
        if (from && to) return labelOf(from) + ' - ' + labelOf(to);
        if (from) return labelOf(from) + ' - ...';
        return placeholder;
      }

      function updateButton() {
        var departPart = rangeLabel(departFrom, departTo, null);
        var returnPart = rangeLabel(returnFrom, returnTo, null);
        dateBtn.textContent = (departPart || returnPart)
          ? (departPart || 'לא נבחר') + ' ← ' + (returnPart || 'לא נבחר')
          : 'בחר תאריכי טיול';
        var clearLink = document.getElementById('clearDates');
        if (clearLink) clearLink.style.display = (departFrom || departTo || returnFrom || returnTo) ? '' : 'none';
      }

      function currentDatesQS() {
        return (departFrom ? '&departFrom=' + departFrom : '')
          + (departTo ? '&departTo=' + departTo : '')
          + (returnFrom ? '&returnFrom=' + returnFrom : '')
          + (returnTo ? '&returnTo=' + returnTo : '');
      }
      function navigate() {
        location.href = '/?max=' + MAX_PRICE + COUNTRY_QS + currentDatesQS();
      }

      var backdrop = null;

      function closeCalendar() {
        if (backdrop && backdrop.parentNode) backdrop.parentNode.removeChild(backdrop);
        backdrop = null;
      }

      function openCalendar() {
        var today = new Date();
        var startYear = today.getFullYear(), startMonth = today.getMonth();
        var maxOrdinal = startYear * 12 + startMonth + 11;
        var viewYear, viewMonth;

        function resetView() {
          viewYear = startYear;
          viewMonth = startMonth;
          if (activeTab === 'return' && departFrom) {
            var parts = departFrom.split('-');
            viewYear = parseInt(parts[0], 10);
            viewMonth = parseInt(parts[1], 10) - 1;
          }
        }
        resetView();

        backdrop = document.createElement('div');
        backdrop.className = 'calendar-modal-backdrop';
        var modal = document.createElement('div');
        modal.className = 'calendar-modal';
        backdrop.appendChild(modal);
        document.body.appendChild(backdrop);
        backdrop.addEventListener('click', function (e) {
          if (e.target === backdrop) closeCalendar();
        });

        function render() {
          var mode = activeTab;
          var monthLabel = new Date(viewYear, viewMonth, 1).toLocaleString('he-IL', { month: 'long', year: 'numeric' });
          var firstWeekday = new Date(viewYear, viewMonth, 1).getDay();
          var daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
          var ordinal = viewYear * 12 + viewMonth;
          var todayIso = toIso(startYear, startMonth, today.getDate());
          var avail = mode === 'depart' ? AVAILABLE_DEPART : AVAILABLE_RETURN;
          var rangeStart = mode === 'depart' ? departFrom : returnFrom;
          var rangeEnd = mode === 'depart' ? departTo : returnTo;
          var minAllowed;
          if (rangeStart && !rangeEnd) {
            minAllowed = rangeStart;
          } else if (mode === 'return' && departFrom) {
            minAllowed = departFrom > todayIso ? departFrom : todayIso;
          } else {
            minAllowed = todayIso;
          }

          var html = '<div class="calendar-tabs">'
            + '<button type="button" class="cal-tab' + (activeTab === 'depart' ? ' active' : '') + '" data-tab="depart">יציאה' + (departFrom ? ' (' + rangeLabel(departFrom, departTo, '') + ')' : '') + '</button>'
            + '<button type="button" class="cal-tab' + (activeTab === 'return' ? ' active' : '') + '" data-tab="return">חזרה' + (returnFrom ? ' (' + rangeLabel(returnFrom, returnTo, '') + ')' : '') + '</button>'
            + '</div>'
            + '<div class="calendar-header">'
            + '<button type="button" class="cal-nav" id="calPrev"' + (ordinal <= startYear * 12 + startMonth ? ' disabled' : '') + '>&#8594;</button>'
            + '<span>' + monthLabel + '</span>'
            + '<button type="button" class="cal-nav" id="calNext"' + (ordinal >= maxOrdinal ? ' disabled' : '') + '>&#8592;</button>'
            + '</div><div class="calendar-weekdays">' + weekdayNames.map(function (w) { return '<span>' + w + '</span>'; }).join('') + '</div>'
            + '<div class="calendar-grid">';
          for (var i = 0; i < firstWeekday; i++) html += '<span class="calendar-day empty"></span>';
          var monthHolidays = [];
          var run = null;
          for (var day = 1; day <= daysInMonth; day++) {
            var iso = toIso(viewYear, viewMonth, day);
            var classes = ['calendar-day'];
            var disabled = iso < minAllowed;
            if (disabled) classes.push('disabled');
            if (!disabled && avail.indexOf(iso) !== -1) classes.push('available');
            if (iso === rangeStart && !rangeEnd) classes.push('range-start');
            var holidayName = HOLIDAYS[iso];
            if (holidayName) classes.push('holiday');
            var extraStyle = '';
            if (holidayName) extraStyle = 'box-shadow: inset 0 0 0 2px ' + holidayColor(holidayName) + ';';
            html += '<button type="button" class="' + classes.join(' ') + '" data-date="' + iso + '"'
              + (disabled ? ' disabled' : '')
              + (extraStyle ? ' style="' + extraStyle + '"' : '')
              + (holidayName ? ' title="' + holidayName + '"' : '')
              + '>' + day + '</button>';
            if (holidayName && run && run.name === holidayName && run.endDay === day - 1) {
              run.endDay = day;
            } else {
              if (run) monthHolidays.push(run);
              run = holidayName ? { name: holidayName, startDay: day, endDay: day } : null;
            }
          }
          if (run) monthHolidays.push(run);
          html += '</div>';
          if (monthHolidays.length) {
            html += '<ul class="holiday-list">' + monthHolidays.map(function (h) {
              var range = h.startDay === h.endDay ? h.startDay : h.startDay + '-' + h.endDay;
              return '<li><span class="dot" style="background:' + holidayColor(h.name) + '"></span>' + range + ': ' + h.name + '</li>';
            }).join('') + '</ul>';
          }
          html += '<p class="calendar-legend"><span class="dot available"></span>יש בו דיל &nbsp; '
            + (rangeStart && !rangeEnd ? 'תאריך התחלה נבחר - לחץ על תאריך סיום (או השאר כך לטווח פתוח)' : 'לחץ על יום להתחלת טווח ' + (mode === 'depart' ? 'היציאה' : 'החזרה'))
            + '</p>'
            + '<button type="button" class="date-btn" id="calSearch" style="width:100%;margin-top:0.5rem;background:#22c55e;color:#052e12;border-color:#22c55e;">חפש טיסות</button>';
          modal.innerHTML = html;

          modal.querySelectorAll('.cal-tab').forEach(function (btn) {
            btn.addEventListener('click', function () {
              activeTab = btn.dataset.tab;
              resetView();
              render();
            });
          });
          var prevBtn = document.getElementById('calPrev');
          var nextBtn = document.getElementById('calNext');
          if (prevBtn) prevBtn.addEventListener('click', function () {
            viewMonth--; if (viewMonth < 0) { viewMonth = 11; viewYear--; }
            render();
          });
          if (nextBtn) nextBtn.addEventListener('click', function () {
            viewMonth++; if (viewMonth > 11) { viewMonth = 0; viewYear++; }
            render();
          });
          var searchBtn = document.getElementById('calSearch');
          if (searchBtn) searchBtn.addEventListener('click', function () {
            closeCalendar();
            updateButton();
            navigate();
          });
          modal.querySelectorAll('.calendar-day[data-date]').forEach(function (btn) {
            btn.addEventListener('click', function () {
              var picked = btn.dataset.date;
              if (mode === 'depart') {
                if (departFrom && !departTo && picked >= departFrom) {
                  departTo = picked;
                } else {
                  departFrom = picked;
                  departTo = null;
                }
              } else {
                if (returnFrom && !returnTo && picked >= returnFrom) {
                  returnTo = picked;
                } else {
                  returnFrom = picked;
                  returnTo = null;
                }
              }
              updateButton();
              render();
            });
          });
        }
        render();
      }

      dateBtn.addEventListener('click', openCalendar);
    })();
  </script>
</body>
</html>`;

  return new Response(html, { headers: { 'content-type': 'text/html; charset=UTF-8' } });
}

export default {
  async scheduled(event, env, ctx) {
    ctx.waitUntil(runScan(env, 'cron'));
  },
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.pathname === '/run') {
      await runScan(env, 'manual');
      return new Response('scan complete, see /', { status: 200 });
    }
    if (url.pathname === '/manifest.webmanifest') {
      return new Response(MANIFEST, {
        headers: { 'content-type': 'application/manifest+json', 'access-control-allow-origin': '*' },
      });
    }
    if (url.pathname === '/icon-192.png') return pngResponse(ICON_192_B64);
    if (url.pathname === '/icon-512.png') return pngResponse(ICON_512_B64);
    if (url.pathname === '/icon-512-maskable.png') return pngResponse(ICON_512_MASKABLE_B64);
    const requested = Number(url.searchParams.get('max'));
    const maxPrice = Number.isFinite(requested) && requested > 0 ? Math.min(requested, 2000) : DEFAULT_MAX_PRICE;
    const monthParam = url.searchParams.get('month');
    const month = monthParam && /^\d{4}-\d{2}$/.test(monthParam) ? monthParam : null;
    const country = url.searchParams.get('country') || null;
    const minNightsParam = Number(url.searchParams.get('minNights'));
    const minNights = Number.isInteger(minNightsParam) && minNightsParam >= 1 && minNightsParam <= 60 ? minNightsParam : null;
    const maxNightsParam = Number(url.searchParams.get('maxNights'));
    const maxNights = Number.isInteger(maxNightsParam) && maxNightsParam >= 1 && maxNightsParam <= 60 ? maxNightsParam : null;
    const isoDate = /^\d{4}-\d{2}-\d{2}$/;
    const departFromParam = url.searchParams.get('departFrom');
    const departFrom = departFromParam && isoDate.test(departFromParam) ? departFromParam : null;
    const departToParam = url.searchParams.get('departTo');
    const departTo = departToParam && isoDate.test(departToParam) ? departToParam : null;
    const returnFromParam = url.searchParams.get('returnFrom');
    const returnFrom = returnFromParam && isoDate.test(returnFromParam) ? returnFromParam : null;
    const returnToParam = url.searchParams.get('returnTo');
    const returnTo = returnToParam && isoDate.test(returnToParam) ? returnToParam : null;
    return renderPage(env, maxPrice, month, country, minNights, maxNights, departFrom, departTo, returnFrom, returnTo);
  },
};
